public class StringBugsAndPerformanceDemo {
    public static void main(String[] args) {
        // 1. Boundary Defense: Avoid StringIndexOutOfBoundsException
        String word = "Learn";
        if (word != null && word.length() > 0) {
            char last = word.charAt(word.length() - 1);
            System.out.println("Safe last char: " + last);
        }

        // 2. Safe Substring Extraction
        int begin = 1;
        int end = 10;
        int safeEnd = Math.min(end, word.length());
        String safeSlice = word.substring(begin, safeEnd);
        System.out.println("Safe slice [1, min(10, len)]: " + safeSlice);

        // 3. Null-Safe Literal Comparison
        String query = null;
        System.out.println("Safe null check: " + "SEARCH".equalsIgnoreCase(query)); // false

        // 4. Regex Escaping
        String file = "archive.tar.gz";
        String[] parts = file.split("\\.");
        System.out.println("Correctly split dot parts: " + parts.length); // 3

        // 5. Performance: Measuring Loop Concatenation vs StringBuilder
        long start = System.currentTimeMillis();
        StringBuilder sb = new StringBuilder(1000);
        for (int i = 0; i < 1000; i++) {
            sb.append(i);
        }
        long duration = System.currentTimeMillis() - start;
        System.out.println("StringBuilder 1000 appends completed in: " + duration + "ms");
    }
}

